import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

import { AuthProvider, useAuth } from './context/AuthContext';

import Navbar from './components/Navbar';
import Footer from './components/Footer';

import MapPage from './components/MapPage';
import ProductsPage from './components/ProductsPage';
import InnovationPage from './components/InnovationPage';
import ArticlesPage from './components/ArticlesPage';
import AdminArticles from './components/AdminArticles';
import AdminDashboard from './components/AdminDashboard';

import Login from './components/Login';
import Register from './components/Register';
import ProtectedRoute from './components/ProtectedRoute';

import './App.css';

// ---------------- HOME PAGE (Bharat Connect Styled) ----------------

function Home() {
  const { user } = useAuth();

  return (
    <div className="bg-[#f8f4ec] min-h-screen py-16">

      {/* Hero Section */}
      <div className="text-center mb-16">
        <h1 className="text-5xl font-extrabold text-[#b2541a] drop-shadow-sm">
          Bharat Connect
        </h1>
        <p className="text-lg text-gray-700 mt-3">
          Discover India's culture • heritage • innovations
        </p>

        {/* Divider */}
        <div className="w-24 h-[3px] bg-[#b2541a] mx-auto mt-4 rounded-full opacity-70"></div>
      </div>

      {/* Feature Cards */}
      <div className="container mx-auto px-6 grid md:grid-cols-2 lg:grid-cols-4 gap-8 mb-16">

        <HomeCard
          to="/map"
          emoji="🗺️"
          title="Interactive Map"
          desc="Explore states & their unique cultural identity"
        />

        <HomeCard
          to="/products"
          emoji="🛍️"
          title="Swadeshi Products"
          desc="Discover authentic Indian handicrafts"
        />

        <HomeCard
          to="/innovations"
          emoji="💡"
          title="Community Innovations"
          desc="Share and vote on ideas from the community"
        />

        <HomeCard
          to="/articles"
          emoji="📝"
          title="Knowledge Hub"
          desc="Read articles about Indian culture & heritage"
        />
      </div>

      {/* If Logged In */}
      {user && (
        <div className="text-center mt-10">
          <p className="text-lg text-gray-800">
            Welcome back, <span className="font-semibold text-[#b2541a]">{user.name}</span>!
          </p>

          {user.role === 'admin' && (
            <div className="mt-4 bg-orange-50 border border-orange-300 text-orange-700 rounded-lg p-4 inline-block shadow">
              <p className="font-medium">Admin Tools Available</p>
              <p className="text-sm">Manage states, products, and platform data</p>
            </div>
          )}
        </div>
      )}

      {/* Not Logged In */}
      {!user && (
        <div className="container mx-auto px-6 mt-12">
          <div className="bg-white rounded-xl shadow-lg border border-orange-200 p-8 text-center">
            <h2 className="text-2xl font-semibold text-[#8b3d1a] mb-3">
              Join the Bharat Connect Community
            </h2>

            <p className="text-gray-600 mb-6">
              Save favourites, share innovations, read and publish articles.
            </p>

            <div className="flex justify-center gap-5">
              <Link
                to="/register"
                className="px-6 py-2 bg-[#b2541a] text-white rounded-lg hover:bg-[#8d3c11] transition shadow"
              >
                Sign Up
              </Link>

              <Link
                to="/login"
                className="px-6 py-2 bg-gray-700 text-white rounded-lg hover:bg-gray-800 transition shadow"
              >
                Sign In
              </Link>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

// -------------- Home Card Component (for cleaner code) --------------



// ---------------------- MAIN APP ------------------------

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="min-h-screen flex flex-col bg-[#f8f4ec]">

          <Navbar />

          <main className="flex-1">
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="/map" element={<MapPage />} />
              <Route path="/products" element={<ProductsPage />} />
              <Route path="/innovations" element={<InnovationPage />} />
              <Route path="/articles" element={<ArticlesPage />} />

              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />

              {/* Admin Protected Routes */}
              <Route
                path="/admin"
                element={
                  <ProtectedRoute requiredRole="admin">
                    <AdminDashboard />
                  </ProtectedRoute>
                }
              />

              <Route
                path="/admin/articles"
                element={
                  <ProtectedRoute requiredRole="admin">
                    <AdminArticles />
                  </ProtectedRoute>
                }
              />
            </Routes>
          </main>

          <Footer />
        </div>

        <ToastContainer
          position="top-right"
          autoClose={3000}
          hideProgressBar={false}
          newestOnTop
          closeOnClick
          draggable
          pauseOnHover
        />
      </Router>
    </AuthProvider>
  );
}

export default App;
